INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('86ad62e9-2d77-5260-8885-e68fd28fda1e','TEXT','A Lantern for the Jetty','Ruby liked helping at the sea fog, especially when there was a small job that nobody had planned. One Wednesday, Ruby noticed the jetty lantern was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
