INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('8cd38b9b-c88b-5e83-afb1-43bcf64f79e4','TEXT','The Rainwater Notebook','Zoe liked helping at the school courtyard, especially when there was a small job that nobody had planned. One Saturday, Zoe noticed the rain gauge was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
