INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('b7244bcd-dd4d-5aa3-87bd-f412e0818b85','TEXT','The Paper Kite Map','Eli liked helping at the open oval, especially when there was a small job that nobody had planned. One Saturday, Eli noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
