INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('ace77f6e-72ba-598b-9a83-69c6045db4a7','TEXT','The Night Garden List','Amara liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Saturday, Amara noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
