INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a8d3e4d0-58ad-57c1-b0a8-67ffb7790713','TEXT','The Museum Window','Kai liked helping at the local museum, especially when there was a small job that nobody had planned. One Friday, Kai noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
