INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('649f4478-b350-5a28-bba5-e543dec4a153','TEXT','The Bicycle Bell Project','Arun liked helping at the bike path, especially when there was a small job that nobody had planned. One Thursday, Arun noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('835203f8-4c14-5170-b4cf-1b3295d244a3','TEXT','The Orange Tree Calendar — A Different Day','Sienna liked helping at the school orchard, especially when there was a small job that nobody had planned. One Tuesday, Sienna noticed the fruit calendar was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
INSERT INTO testlets (id,section_id,stimulus_id,title,testlet_order,is_branching_node,navigation_locked,calculator_allowed,instructions) VALUES ('b2655eb0-7878-516a-a184-f669f2f3d09c','4f77aae3-7159-53bf-8271-89ae5960964c','649f4478-b350-5a28-bba5-e543dec4a153','F',8,TRUE,FALSE,NULL,'Complete this F testlet. Answer every question before continuing.');
